insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-17','verbeterd','Offertes','Echte offerte zichtbaar op het Informatie-tabblad',
   'Het Informatie-tabblad van een offerte-dossier toont niet langer een verouderd voorbeeld, maar de echte offerte: gemaakt in EVA (met versies en concept-markering) of een PDF die je zelf aan het dossier koppelt. Is er nog geen offerte, dan koppel je die met één knop.');
